import type { SymbolEntry } from './types'

export interface CategoryInfo {
  id: string
  title: string
  icon?: string
}

/** Generated by scripts/build-categories.py. */
export interface CategoryMapFile {
  source: string
  order: CategoryInfo[]
  hidden?: string[]
  symbols: Record<string, string>
}

export interface CategoryBucket {
  id: string
  title: string
  icon?: string
  symbols: SymbolEntry[]
}

export function categorizeSymbols(
  symbols: SymbolEntry[],
  map: CategoryMapFile,
): CategoryBucket[] {
  const hidden = new Set(map.hidden ?? ['indices', 'currencies'])
  const buckets = new Map<string, CategoryBucket>()
  for (const { id, title, icon } of map.order) {
    buckets.set(id, { id, title, icon, symbols: [] })
  }
  const other: CategoryBucket = {
    id: 'other',
    title: 'Other',
    icon: 'ellipsis.circle',
    symbols: [],
  }

  for (const symbol of symbols) {
    const cid = map.symbols[symbol.name] ?? 'other'
    if (hidden.has(cid)) continue
    const bucket = buckets.get(cid) ?? other
    bucket.symbols.push(symbol)
  }

  const out = [...buckets.values(), other].filter((b) => b.symbols.length > 0)
  for (const bucket of out) {
    bucket.symbols.sort((a, b) => a.name.localeCompare(b.name))
  }
  return out
}
